update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p071","body":"دھڑکن دھن کسی گیت کی گا ہی گئی\nپھر کسی بہانے سے تیری یاد آ ہی گئی\n\nسبھی ارمان راکھ تھے ہوا کے ہوئے\nہوا بھی ایسی چلی کہ سب بجھا ہی گئی\n\nساون کی گھٹاوں سے گرے درخت بھی بہت\nپر ساون کی گھٹا انھیں بھی بھیگا ہی گئی\n\nیہ آنکھیں جن میں دو اشکوں کی جگہ تک نہیں\nیہی آنکھیں درد کا ساگر بھی چھپا ہی گئی\n\nاب فرصت کہاں کہ تجھے یاد بھی آئیں احمد ؔ\nپر تیری یاد ہمیں بھولے سے آ ہی گئی"},{"slug":"tum-p072","body":"ہے ذرا سی آنکھ پٔرنم تو کیا ہوا\nہوئی ہے زندگی برہم تو کیا ہوا\n\nرہے گی یاد یہ شام اسے کٔھل کے جی لے\nہو جائے بھی اگر روشنی کم تو کیا ہوا\n\nان خوابوں میں حقیقتوں کی تلخیاں نہیں شامل\nان میں نہیں شامل تیری فرقت کا غم تو کیا ہوا\n\nپہنچ سے دٔور نظر کی تاک میں جو ایک ستارہ ہے\nکبھی ہو جائے جو یہ بھی مدہم تو کیا ہوا\n\nکیا ہوا جو ملے ہیں زندگی کے اس دَور میں احمد ؔ\nبس ذرا سے دل جلے اور اداس ہیں ہم تو کیا ہوا"},{"slug":"tum-p073","body":"دل شکستہ ضرور ہے مگر ہارا نہیں ہے\nمنزل رائیگاں سہی سفر ناکارہ نہیں ہے\n\nکیا دوست، کیا محبت، کیا ہی منزل اوریہ نیا شہر\nاحمد ؔ  ہم یہاں سبھی کے ہیں پر کوئی ہمارا نہیں ہے"},{"slug":"tum-p074","body":"اب کہ تنہا ہے دل اور سہارا کوئی نہیں\nڈوب چلے ہیں ساگر میں اور کنارہ کوئی نہیں\n\nشب ہجر کئی یادوں کے گھنیرے جنگل میں\nلب بام تنہا بیٹھے ہیں اور چاند ستارہ کوئی نہیں\n\nیوں تو گزر ہوا ہوگا کئی حسیں راہگزاروں سے\nہر پل سفر کو چلتے ہیں اور یاد نظارہ کوئی نہیں\n\nکیا دوست، کیا محبت، کیا ہی منزل اوریہ نیا شہر\nاحمد ہم یہاں سبھی کے ہیں اور بس ہمارا کوئی نہیں"},{"slug":"tum-p075","body":"تم سے پہلے یہ نسبت روحانی نہیں تھی\nغموں سے اپنی دوستی پرانی نہیں تھی\n\nکئی قصے تھے جہاں میں مقبول\nمحبت کی مگر کوئی کہانی نہیں تھی\n\nاپنی آنکھوں میں کچھ خواب پشیماں بھی نہ ہوں\nاس قدر بھی زائل اپنی جوانی نہیں تھی\n\nیہ لفظ بکھرتے جڑتے تھے اسی کے سامنے\nبات وہ نکل جاتی تھی جو بتانی نہیں تھی\n\nاحمد ؔ کسی کو فقط عشق بھی کرنا تھا\nپھر اپنی آبرو بھی گنوانی نہیں تھی"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
